import assert from 'node:assert/strict';
import {writeFileSync,mkdirSync} from 'node:fs';
import * as c from '../dayboard/core.js';
import * as d from '../dayboard/dashboard-domain.js';
import * as o from '../dayboard/task-order.js';
const results=[];
function test(name,fn){try{fn();results.push({name,passed:true});console.log('PASS',name);}catch(e){results.push({name,passed:false,error:e.stack});console.error('FAIL',name,e);}}
const date='2026-09-07',now=+c.at(date,'08:00');
const state=(items=[],blocks=[],settings={})=>({items,blocks,settings:{...c.DEFAULTS,...settings}});
const task=(title,values={})=>c.newItem({title,...values});
test('Additive task fields keep defaults; no existing records are rewritten',()=>{const i=task('A');assert.equal(i.pinned,false);assert.equal(i.pinIndex,null);assert.equal(i.estimatedMinutes,30);assert.equal(i.recommendationRank,null);});
test('Rule recommendation favors deadline/importance and never pretends to call GPT',()=>{const a=task('A',{deadline:date,importance:3}),b=task('B',{importance:1});assert.equal(o.orderedTasks([b,a],{},date)[0].id,a.id);assert.equal(o.hasGPTOrder(a,now),false);});
test('Fresh saved GPT rank is used; stale or future ranks expire safely',()=>{const a=task('A',{importance:3}),b=task('B',{importance:1,recommendationRank:0,recommendationAt:new Date(now).toISOString()});assert.equal(o.orderedTasks([a,b],{},date,{now})[0].id,b.id);assert.equal(o.hasGPTOrder(b,now+8*86400000),false);assert.equal(o.hasGPTOrder({...b,recommendationAt:'2027-01-01T00:00:00Z'},now),false);});
test('Manual move and recommendation restore preserve a pinned slot',()=>{const a=task('A'),b=task('B',{pinned:true,pinIndex:1}),cc=task('C');const items=[a,b,cc],m=o.moveTaskOrder(items,cc.id,a.id);assert.deepEqual(m.map(i=>i.id),[cc.id,b.id,a.id]);const restored=o.orderedTasks(items,{taskOrder:m.map(i=>i.id)},date,{recommended:true});assert.equal(restored[1].id,b.id);assert.throws(()=>o.moveTaskOrder(items,b.id,a.id),/핀/);});
test('Legacy colliding pins and deleted manual IDs cannot duplicate or lose tasks',()=>{const a=task('A',{pinned:true,pinIndex:999}),b=task('B',{pinned:true,pinIndex:999}),cc=task('C');const r=o.orderedTasks([a,b,cc],{taskOrder:['deleted',cc.id]},date);assert.equal(new Set(r.map(i=>i.id)).size,3);assert(r.every(Boolean));});
test('Dashboard shows today or unplaced tasks, not future-reserved or completed work',()=>{const a=task('A'),b=task('B'),cc=task('C',{status:'done'});const s=state([a,b,cc],[{id:c.uid(),taskId:b.id,start:c.iso(c.addDays(date,1),'09:00'),end:c.iso(c.addDays(date,1),'10:00')}]);assert.deepEqual(d.dashboardTasks(s,date,'all',now).map(i=>i.id),[a.id]);assert.equal(d.dashboardTasks(s,date,'today',now).length,0);});
test('Parent deadline and importance apply to leaf work without changing the original',()=>{const p=task('P',{kind:'project',deadline:date,importance:3}),a=task('A',{parentId:p.id,importance:1});const e=d.effectiveTask(a,[p,a]);assert.equal(e.deadline,date);assert.equal(e.importance,3);assert.equal(a.deadline,null);});
test('Project next action and remaining work count leaf tasks only',()=>{const p=task('P',{kind:'project'}),a=task('A',{parentId:p.id,estimatedMinutes:300}),b=task('B',{kind:'subtask',parentId:a.id,estimatedMinutes:60}),cc=task('C',{kind:'subtask',parentId:a.id,status:'done',progress:100});const r=d.projectSummary(p,state([p,a,b,cc]),date);assert.equal(r.remaining,1);assert.equal(r.minutes,60);assert.equal(r.next.id,b.id);});
test('Capacity merges overlapping meetings and accounts for lunch/buffers once',()=>{const a={start:c.iso(date,'09:00'),end:c.iso(date,'11:00'),source:'google'},b={start:c.iso(date,'10:00'),end:c.iso(date,'12:00'),source:'google'};assert.equal(d.availableMinutes(state([],[a,b],{bufferMinutes:0}),date,date,new Set(),now),300);});
test('Competing deadlines share capacity; parent and children are never double-counted',()=>{const p=task('P',{kind:'project',deadline:date,estimatedMinutes:500}),a=task('A',{parentId:p.id,deadline:date,estimatedMinutes:45}),b=task('B',{deadline:date,estimatedMinutes:45});const r=d.deadlineRisks(state([p,a,b],[],{workStart:'09:00',workEnd:'10:00',bufferMinutes:0}),date,now);assert(r.every(x=>x.demand===90&&x.capacity===60&&x.level==='danger'));assert.equal(r.find(x=>x.item.id===p.id).remaining,45);});
test('Already reserved work is not subtracted from both capacity and task demand',()=>{const a=task('A',{deadline:date,estimatedMinutes:60});const b={taskId:a.id,source:'app',start:c.iso(date,'09:00'),end:c.iso(date,'10:00')};assert.equal(d.availableMinutes(state([a],[b],{workStart:'09:00',workEnd:'10:00',bufferMinutes:0}),date,date,new Set([a.id]),now),60);});
test('Natural task parser resolves dates, duration and exact project without saving',()=>{const p=task('가을 발표 준비',{kind:'project'});const r=d.parseQuickTask('내일까지 결과 정리, 1시간 30분, 가을 발표 준비 프로젝트에 넣어줘',state([p]),date);assert.equal(r.item.deadline,'2026-09-08');assert.equal(r.item.estimatedMinutes,90);assert.equal(r.item.parentId,p.id);assert(r.item.title.includes('결과 정리'));assert(!r.item.title.includes('프로젝트'));});
test('Natural parser rejects invalid dates and flags ambiguous appointment times',()=>{assert.throws(()=>d.parseQuickTask('2026-02-30 자료',state(),date),/날짜/);assert.throws(()=>d.parseQuickTask('업무1\n업무2',state(),date),/한 번에/);const r=d.parseQuickTask('내일 오전 9시 미팅, 60분',state(),date);assert(r.warnings.length>0);assert.equal(r.item.status,'todo');});
test('Pin undo works for old records without pin fields',()=>{const a=task('A');delete a.pinned;delete a.pinIndex;let before=state([a]);const after=c.applyLocal(before,[c.upsert('items',{id:a.id,pinned:true,pinIndex:0})]);const reverted=c.applyLocal(after,c.inverseOps(before,after));assert.equal(reverted.items[0].pinned,false);});
test('First manual-order undo restores recommended order instead of retaining added field',()=>{const a=task('A'),b=task('B'),before=state([a,b]);const after=c.applyLocal(before,[{collection:'settings',action:'merge',data:{taskOrder:[b.id,a.id]}}]);const reverted=c.applyLocal(after,c.inverseOps(before,after));assert.deepEqual(reverted.settings.taskOrder,[]);});
test('Local planner follows pinned sequence and respects inherited project deadline',()=>{const future=c.addDays(c.dateKey(),2),p=task('P',{kind:'project',deadline:c.addDays(future,-1)}),a=task('A',{importance:1,pinned:true,pinIndex:0,estimatedMinutes:30}),b=task('B',{importance:3,estimatedMinutes:30}),expired=task('Expired',{parentId:p.id});const s=state([p,a,b,expired],[],{weekendStart:'09:00',weekendEnd:'18:00'});const r=c.schedulePlan(s,future,2);assert.equal(r.operations.find(x=>x.action==='upsert').data.taskId,a.id);assert(r.skipped.some(x=>x.title==='Expired'));});
mkdirSync('dayboard-test-output',{recursive:true});writeFileSync('dayboard-test-output/v2-domain.json',JSON.stringify({passed:results.filter(r=>r.passed).length,failed:results.filter(r=>!r.passed).length,results},null,2));if(results.some(r=>!r.passed))process.exitCode=1;
